local a={}a.SKY="3"a.GND="c"a.LINE="0"a.CRAFT="d"a.pxPerDeg=1.6;local b={[0]={[0]=1,[1]=4,[2]=16},[1]={[0]=2,[1]=8,[2]=false}}local function c(d)local e={{ang=0,half=d}}local f=math.max(2,math.floor(d*0.09))local g=math.max(4,math.floor(d*0.17))for h=5,20,5 do local i=h%10==0 and g or f;e[#e+1]={ang=h,half=i}e[#e+1]={ang=-h,half=i}end;return e end;function a.draw(j,k,l,m,n,o,p)k,l=k or 0,l or 0;p=p or a.CRAFT;local d=m*2;local q,r=d/2,n*3/2;local s=math.tan(math.rad(l))local t=r+k*a.pxPerDeg;local u=c(d)local function v(w,x)local y=w-q;for z,A in ipairs(u)do local B=t-A.ang*a.pxPerDeg+y*s;if math.floor(B+0.5)==x and math.abs(y)<=A.half then return true end end;return false end;for C=1,n do for D=1,m do local E,F=(D-1)*2,(C-1)*3;local G=F+1.5<t+(E+1-q)*s and a.SKY or a.GND;local H=0;for I=0,1 do for J=0,2 do local K=b[I][J]if K and v(E+I,F+J)then H=H+K end end end;if H==0 then j:setPixel(D,C," ",G,G)else j:setPixel(D,C,string.char(128+H),a.LINE,G)end end end;local L=math.floor(n/2)+1;local M=math.floor(m/2)local N=1;local O=math.max(N+1,math.floor(m*0.34))for D=1,m do local P=D-M;if math.abs(P)>N and math.abs(P)<=O then j:setPixel(D,L," ",p,p)end end(a.BODIES[o]or a.BODIES.circle)(j,M,L,m,n,p)end;local function Q(j,R,S)return(j:getBg(R,S)or"f"):sub(1,1)end;a.BODIES={circle=function(j,R,S,m,n,T)j:setPixel(R,S,string.char(7),T,Q(j,R,S))end,ring=function(j,R,S,m,n,T)j:setPixel(R-1,S,"(",T,Q(j,R-1,S))j:setPixel(R,S,string.char(7),T,Q(j,R,S))j:setPixel(R+1,S,")",T,Q(j,R+1,S))end,square=function(j,R,S,m,n,T)j:setPixel(R,S," ",T,T)end,diamond=function(j,R,S,m,n,T)j:setPixel(R,S,string.char(4),T,Q(j,R,S))end}return a